contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint ms, uint dep, uint am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep)); require(dep <= 1000000000000000000000000000000);
        require(address(this).balance >= dep);
        c.SetMinSum(ms); if (__ESBMC_reverted()) return;
        uint beforeC = address(c).balance;
        c.Deposit{value: dep}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        require(balBefore >= ms);
        require(balBefore >= am);
        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterC = address(c).balance;
        assert(!reverted && balAfter == balBefore - am && beforeC + dep == afterC + am);
    }
    receive() external payable {}
}

