import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 ms, uint256 dep, uint256 am) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= dep);
        try c.SetMinSum(ms) {} catch { return; }
        uint beforeC = address(c).balance;
        try c.Deposit{value: dep}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        vm.assume(balBefore >= ms);
        vm.assume(balBefore >= am);
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint afterC = address(c).balance;
        assertTrue(!reverted && balAfter == balBefore - am && beforeC + dep == afterC + am);
    }

    function testFuzz_run(uint256 ms, uint256 dep, uint256 am) public {
        _run(ms, dep, am);
    }

    receive() external payable {}
}
